const body = $json.body ?? $json;
const data = body.data ?? body;
const key = data.key ?? {};
const message = data.message ?? {};

const remoteJid = String(key.remoteJid ?? '');
const telefone = remoteJid.replace(/@.*$/, '').replace(/\D/g, '');
const fromMe = Boolean(key.fromMe);
const isGroup = remoteJid.endsWith('@g.us');

let text = '';
let mensagemDeAudio = '';
if (message.conversation) text = message.conversation;
else if (message.extendedTextMessage?.text) text = message.extendedTextMessage.text;
else if (message.audioMessage) mensagemDeAudio = JSON.stringify(message.audioMessage);
else if (message.imageMessage?.caption) text = message.imageMessage.caption;

const instance = String(body.instance ?? data.instance ?? '');
const pushName = String(data.pushName ?? '');
const idMensagem = String(key.id ?? `m-${Date.now()}`);
const timestamp = Number(data.messageTimestamp ?? Math.floor(Date.now()/1000));

return [{
  json: {
    instancia: instance,
    telefone,
    fromMe,
    is_group: isGroup,
    mensagem: text,
    mensagem_de_audio: mensagemDeAudio,
    pushName,
    id_mensagem: idMensagem,
    timestamp,
    remoteJid
  }
}];

const produtos = $input.all().map(i => i.json);
const cliente = $('Upsert Cliente (RAG)').first().json;
const pizzaria = $('Carregar Pizzaria').first().json;
const info = $('Info').first().json;

// Group by category
const byCat = {};
for (const p of produtos) {
  const cat = p.categoria || 'outro';
  if (!byCat[cat]) byCat[cat] = [];
  byCat[cat].push(`- ${p.nome} (R$ ${Number(p.preco).toFixed(2)}) [id:${p.id}]${p.descricao ? ` — ${p.descricao}` : ''}`);
}
let cardapio = '';
for (const cat of Object.keys(byCat).sort()) {
  cardapio += `\n## ${cat.toUpperCase()}\n${byCat[cat].join('\n')}\n`;
}
if (!cardapio.trim()) cardapio = '(cardápio vazio)';

// RAG cliente
let ragContext = '';
if (cliente && cliente.total_pedidos && cliente.total_pedidos > 0) {
  ragContext = `\n\nCLIENTE RECORRENTE:\nNome: ${cliente.nome || 'sem nome'}\nEndereço padrão: ${cliente.endereco_padrao || 'não informado'}\nPreferências: ${cliente.preferencias || 'nenhuma'}\nTotal de pedidos: ${cliente.total_pedidos} | Total gasto: R$ ${Number(cliente.total_gasto||0).toFixed(2)}\nÚltima visita: ${cliente.ultima_visita || 'nunca'}`;
  if (cliente.historico_pedidos && Array.isArray(cliente.historico_pedidos) && cliente.historico_pedidos.length > 0) {
    const last = cliente.historico_pedidos.slice(-3).map(h => `• ${h.date || ''}: ${h.items || ''} (R$ ${Number(h.total||0).toFixed(2)})`).join('\n');
    ragContext += `\nÚltimos pedidos:\n${last}`;
  }
} else {
  ragContext = `\n\nCLIENTE NOVO: primeiro contato (telefone ${info.telefone}).`;
}

const basePrompt = pizzaria.prompt_personalizado || 'Você é o PizzaBot, assistente virtual da pizzaria. Seja simpático, rápido e ajude o cliente a fechar o pedido.';

const systemMessage = `${basePrompt}\n\n## CARDÁPIO DISPONÍVEL${cardapio}\n${ragContext}\n\nINSTRUÇÕES:\n- Use APENAS itens do cardápio acima (já filtrado por disponíveis).\n- Ao confirmar o pedido use a tool Registrar_Pedido passando o array de itens com {nome, qtd, preco_unit}.\n- Após registrar o pedido, se o cliente quiser pagar via PIX/cartão, use Gerar_Pagamento_PIX.\n- Use Escalar_Humano se o cliente pedir falar com atendente ou estiver muito irritado.\n- Use Atualizar_Obs_Pedido para adicionar observações ao pedido já registrado.\n- Sempre confirme o endereço de entrega antes de registrar o pedido.\n- Identifique a forma de pagamento (pix, cartao ou dinheiro).`;

return [{
  json: {
    systemMessage,
    userMessage: info.mensagem || '',
    sessionId: `${pizzaria.id}-${info.telefone}`,
    pizzaria_id: pizzaria.id,
    cliente_id: cliente.id,
    telefone: info.telefone,
    instancia: info.instancia
  }
}];
